const MODULES = [
  {id:'intro',title:'Introduction to Accuracy Assessment',short:'Introduction',icon:'⌖',desc:'What map accuracy means, why it matters, and where it is used.',time:'8 MIN',sections:[
    {heading:'What is accuracy assessment?',body:'Accuracy assessment is the process of comparing a map or remotely sensed classification with reliable reference information to evaluate how well the mapped classes represent conditions on the ground. It helps us understand how much confidence we should place in a map and in decisions based on that map.'},
    {heading:'Why does it matter?',body:'A land-cover map may guide conservation, urban planning, flood-risk analysis, habitat monitoring and public investment. If wetlands are mapped as built-up land, or water is mapped as vegetation, decisions based on the map may be misleading. Accuracy assessment measures and communicates these errors.'},
    {heading:'A simple example',body:'Imagine a satellite image is classified into water, vegetation, built-up land and agriculture. We select locations for which we know the actual land cover, compare those reference labels with the map labels, and summarize the agreements and disagreements.'}
  ]},
  {id:'accuracy-precision',title:'Accuracy vs. Precision',short:'Accuracy vs Precision',icon:'◎',desc:'Distinguish closeness to truth from consistency of repeated results.',time:'10 MIN',sections:[
    {heading:'Two different ideas',body:'Accuracy describes how close a measurement or mapped label is to the accepted reference value. Precision describes how consistent repeated measurements or observations are with one another. A dataset can be precise but inaccurate, accurate on average but imprecise, both, or neither.'},
    {heading:'Try the target',body:'Click inside the target to place observations. Watch how the mean distance from the bullseye (a simple accuracy illustration) differs from the spread around the average point (a simple precision illustration). This is a conceptual demonstration, not a formal statistical estimator.'}
  ]},
  {id:'workflow',title:'Accuracy Assessment Workflow',short:'Assessment Workflow',icon:'⇢',desc:'Plan reference data, sample locations, compare classes and report results.',time:'9 MIN',sections:[
    {heading:'A defensible workflow',body:'Start by defining the map classes, map date, assessment objective and reference-data requirements. Design a probability-based sample, collect independent reference labels, compare them with the map, construct an error matrix, calculate suitable accuracy measures, and report the sampling design and limitations.'},
    {heading:'Reference data quality',body:'Reference observations should be more reliable than the map being evaluated, sufficiently detailed to distinguish the classes, and temporally appropriate. Field observations, authoritative datasets and high-resolution imagery can be useful, but each has positional, thematic and temporal limitations.'}
  ]},
  {id:'sampling',title:'Sampling Strategies',short:'Sampling Strategies',icon:'▦',desc:'Explore random, systematic and stratified sampling on a land-cover grid.',time:'12 MIN',sections:[
    {heading:'Why sampling design matters',body:'It is rarely practical to inspect every pixel. A sample provides evidence about map quality, but the way points are selected affects bias, precision and the interpretation of the results. A probability sampling design gives each eligible unit a known, non-zero chance of selection.'},
    {heading:'Explore the grid',body:'Choose a sampling strategy and generate points on the illustrative land-cover grid. Random sampling selects locations across the full area; systematic sampling uses a regular interval with a starting point; stratified sampling samples separately within mapped classes.'}
  ]},
  {id:'sample-size',title:'Sample Size Calculator',short:'Sample Size',icon:'∑',desc:'Estimate a simple sample size for a proportion with a chosen confidence level.',time:'8 MIN',sections:[
    {heading:'A basic proportion formula',body:'For a simple random sample and an estimated proportion, a commonly taught starting formula is n = Z² p(1 − p) / E². Here Z is the standard normal critical value, p is the anticipated proportion (often expected accuracy), and E is the desired margin of error.'},
    {heading:'Important assumptions',body:'This is a simplified planning calculation. It does not automatically account for stratification, unequal allocation, clustering, finite population correction, non-response, design effects or class-specific precision requirements. Round the result up to the next whole observation and justify the final design.'}
  ]},
  {id:'sampling-match',title:'Sampling Methods: Match the Statements',short:'Sampling Match',icon:'⇄',desc:'Match each statement to random or stratified sampling and receive immediate feedback.',time:'6 MIN',sections:[{heading:'Check your understanding of sampling',body:'Sort each statement into the sampling method it describes. Random sampling selects units from the full population; stratified sampling selects units separately within defined groups or classes. Some statements describe likely advantages or limitations, rather than the selection procedure itself.'}]},
  {id:'confusion-matrix',title:'The Confusion Matrix',short:'Confusion Matrix',icon:'▤',desc:'Select map validation samples, build a live confusion matrix, and explore accuracy measures step by step.',time:'12 MIN',sections:[
    {heading:'What does the matrix show?',body:'A confusion matrix cross-tabulates mapped classes against reference classes. The diagonal contains agreements. Off-diagonal cells show disagreements. Always label the axes clearly because row and column orientation determines how you calculate user’s and producer’s accuracy.'},
    {heading:'Matrix convention used in this course',body:'In the editable worksheet below, rows represent MAP / CLASSIFIED classes and columns represent REFERENCE classes. Therefore, row totals are mapped-class totals and column totals are reference-class totals. Producer’s accuracy uses the reference column total; user’s accuracy uses the mapped row total.'}
  ]},
  {id:'metrics',title:'Accuracy Metrics & Calculations',short:'Accuracy Metrics',icon:'ƒ',desc:'Calculate overall, producer’s and user’s accuracy, errors and Kappa.',time:'14 MIN',sections:[
    {heading:'Overall accuracy',body:'Overall accuracy is the number of correctly classified reference observations divided by the total number of reference observations. It summarizes the proportion of all sampled locations that agree.'},
    {heading:'Producer’s and user’s accuracy',body:'Producer’s accuracy is calculated for a reference class: correctly mapped observations divided by the reference total for that class. Its complement is omission error. User’s accuracy is calculated for a mapped class: correctly mapped observations divided by the mapped total for that class. Its complement is commission error.'},
    {heading:'Kappa coefficient',body:'Kappa compares observed agreement with the agreement expected from the matrix margins: κ = (Pₒ − Pₑ) / (1 − Pₑ). It is sensitive to prevalence and marginal distributions, so report the confusion matrix and class-specific measures as well. Do not interpret Kappa as a complete substitute for accuracy statistics.'}
  ]},
  {id:'practice-lab',title:'GIS Practice',short:'GIS Practice',icon:'⌖',desc:'Explore an illustrative satellite basemap and practice reference checks.',time:'10 MIN',sections:[
    {heading:'Map interpretation exercise',body:'The map below uses a public satellite basemap for visual context and illustrative sample locations. The coloured markers are teaching examples, not field-verified reference observations. In a real assessment, each sample would need a dated, documented and independent reference label.'},
    {heading:'Practice decision',body:'Select a sample marker to inspect its mapped class and example reference class. Decide whether the point is an agreement or disagreement. The demonstration data are synthetic and should not be cited as a real accuracy assessment.'}
  ]},
  {id:'final-quiz',title:'Course Assessment',short:'Assessment',icon:'✎',desc:'Test your understanding with a timed assessment and instant feedback.',time:'12 MIN',sections:[
    {heading:'Before you begin',body:'The assessment contains 16 questions, including numerical calculations of overall accuracy, producer’s accuracy, user’s accuracy, omission error, commission error and Kappa. Each correct answer earns 10 points. You may review the explanations after submitting. Your highest recorded quiz score is retained in your learning progress.'}
  ]},
  {id:'reflection',title:'Reflection, Leaderboard & Certificate',short:'Achievement',icon:'♛',desc:'Reflect on what you learned, view class scores and print your certificate.',time:'5 MIN',sections:[
    {heading:'Bring the ideas together',body:'A reliable accuracy assessment is more than a single percentage. It depends on a clear map legend, appropriate reference data, a defensible probability sample, a correctly interpreted error matrix and transparent reporting.'}
  ]}
];

const QUIZ = [
 {q:'What is the main purpose of accuracy assessment?',o:['To make a map more colourful','To compare mapped labels with reliable reference information','To increase the number of pixels','To remove all uncertainty'],a:1,e:'Accuracy assessment evaluates agreement between map classifications and reference observations.'},
 {q:'A map is precise but consistently labels a class incorrectly. What does this describe?',o:['High accuracy and high precision','Low precision and high accuracy','High precision but low accuracy','Neither accuracy nor precision'],a:2,e:'Repeated results can be tightly grouped (precise) but far from the accepted truth (inaccurate).'},
 {q:'Which sample design selects locations separately within mapped classes?',o:['Simple random','Systematic','Stratified','Convenience'],a:2,e:'Stratified sampling divides the population into strata and samples within each stratum.'},
 {q:'In this website’s confusion matrix, what do the rows represent?',o:['Reference classes','Map / classified classes','Confidence intervals','Sample dates'],a:1,e:'Rows represent map classes and columns represent reference classes.'},
 {q:'Producer’s accuracy uses which denominator in this matrix convention?',o:['Mapped row total','Reference column total','Grand total squared','Number of map classes'],a:1,e:'Producer’s accuracy is the diagonal count divided by the reference total for that class (column total).'},
 {q:'The complement of user’s accuracy is:',o:['Omission error','Overall accuracy','Commission error','Expected agreement'],a:2,e:'Commission error = 1 − user’s accuracy.'},
 {q:'Why should reference data be temporally appropriate?',o:['To make the file smaller','To ensure the reference describes the map date or period','To increase the number of classes','To avoid using a sampling design'],a:1,e:'Land cover can change. A reference label from a different date may not represent conditions when the map was produced.'},
 {q:'A sample has 72 correct classifications out of 90 reference points. What is overall accuracy?',o:['72%','80%','90%','18%'],a:1,e:'OA = (72 ÷ 90) × 100 = 80%.'},
 {q:'For a reference class, 42 observations are correctly mapped and the reference column total is 50. What is producer’s accuracy?',o:['42%','50%','84%','92%'],a:2,e:'PA = (42 ÷ 50) × 100 = 84%.'},
 {q:'For a mapped class, 36 observations are correct and the mapped row total is 45. What is user’s accuracy?',o:['75%','80%','84%','90%'],a:1,e:'UA = (36 ÷ 45) × 100 = 80%.'},
 {q:'If producer’s accuracy is 84%, what is omission error?',o:['16%','84%','100%','184%'],a:0,e:'Omission error = 100% − PA = 100% − 84% = 16%.'},
 {q:'If user’s accuracy is 76%, what is commission error?',o:['24%','76%','100%','176%'],a:0,e:'Commission error = 100% − UA = 100% − 76% = 24%.'},
 {q:'A confusion matrix has diagonal counts 18, 24, 30 and 8. The total sample is 100. What is overall accuracy?',o:['70%','80%','88%','100%'],a:1,e:'Correct observations = 18 + 24 + 30 + 8 = 80. Therefore OA = 80/100 × 100 = 80%.',},
 {q:'A mapped class has 60 samples in its row, of which 48 are on the diagonal. What is commission error?',o:['12%','20%','48%','80%'],a:1,e:'UA = 48/60 = 80%. Commission error = 1 − 0.80 = 0.20 = 20%.'},
 {q:'For a class, the reference column total is 80 and 68 are correctly classified. What is omission error?',o:['10%','12%','15%','85%'],a:2,e:'PA = 68/80 = 85%. Omission error = 100% − 85% = 15%.'},
 {q:'If observed agreement Pₒ = 0.80 and expected agreement Pₑ = 0.50, what is Kappa?',o:['0.30','0.50','0.60','1.30'],a:2,e:'κ = (Pₒ − Pₑ)/(1 − Pₑ) = (0.80 − 0.50)/(1 − 0.50) = 0.30/0.50 = 0.60.'}
];

let studentName = localStorage.getItem('gis_lab_name') || '';
let studentId = studentName ? (localStorage.getItem('gis_lab_student_id_'+studentName.toLowerCase()) || makeId()) : makeId();
let progress = readProgress(studentId);
let activeModule = 0;
let leaderboardCache = [];
let quizState = null;
let mapInstance = null;
let dartPoints = [];

function makeId(){return (window.crypto&&crypto.randomUUID)?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function readProgress(id){try{return JSON.parse(localStorage.getItem('gis_lab_progress_'+id)||'{"completed":[],"score":0,"quizScore":0,"quizAnswers":{},"reflection":""}')}catch{return {completed:[],score:0,quizScore:0,quizAnswers:{},reflection:''}}}
function saveProgress(){localStorage.setItem('gis_lab_progress_'+studentId,JSON.stringify(progress));saveLocalLeaderboard();updateProgressUI()}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const region=document.getElementById('toast-region');const item=document.createElement('div');item.className='toast';item.textContent=message;region.appendChild(item);setTimeout(()=>item.remove(),3600)}
function setSyncStatus(mode,label){const el=document.getElementById('sync-status');if(!el)return;el.classList.toggle('online',mode==='online');el.innerHTML='<i></i> '+label}
function loadLeaderboard(){try{leaderboardCache=JSON.parse(localStorage.getItem('gis_lab_demo_leaderboard')||'[]')}catch(e){leaderboardCache=[]}return leaderboardCache}
function saveLocalLeaderboard(){let rows=JSON.parse(localStorage.getItem('gis_lab_demo_leaderboard')||'[]');const found=rows.findIndex(x=>x.student_id===studentId);const row={student_id:studentId,student_name:studentName,total_score:progress.score||0,completed_modules:progress.completed||[]};if(found>=0)rows[found]=row;else rows.push(row);localStorage.setItem('gis_lab_demo_leaderboard',JSON.stringify(rows));leaderboardCache=rows}
function updateProgressUI(){const completed=progress.completed||[];const pct=Math.round(completed.length/MODULES.length*100);const text=document.getElementById('sidebar-progress-text');const bar=document.getElementById('sidebar-progress-bar');if(text)text.textContent=pct+'%';if(bar)bar.style.width=pct+'%';document.querySelectorAll('.nav-item').forEach((el,i)=>{el.classList.toggle('done',completed.includes(MODULES[i].id));const num=el.querySelector('.nav-number');if(num)num.textContent=completed.includes(MODULES[i].id)?'✓':String(i+1)})}
function showApp(){saveLocalLeaderboard();setSyncStatus('local','Saved on this device');document.getElementById('login-screen').classList.add('hidden');document.getElementById('app-shell').classList.remove('hidden');document.getElementById('top-student-name').textContent=studentName;document.getElementById('student-avatar').textContent=(studentName[0]||'L').toUpperCase();buildNavigation();updateProgressUI();renderHome()}
function buildNavigation(){const nav=document.getElementById('course-nav');nav.innerHTML=MODULES.map((m,i)=>`<button class="nav-item ${i===activeModule?'active':''} ${progress.completed.includes(m.id)?'done':''}" data-index="${i}"><span class="nav-number">${progress.completed.includes(m.id)?'✓':i+1}</span><span>${m.short}</span></button>`).join('');nav.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>goToModule(Number(b.dataset.index))))}
function goToModule(index){activeModule=Math.max(0,Math.min(index,MODULES.length-1));document.getElementById('breadcrumb-current').textContent=MODULES[activeModule].title;document.querySelectorAll('.nav-item').forEach((b,i)=>b.classList.toggle('active',i===activeModule));document.getElementById('sidebar').classList.remove('open');renderModule(activeModule);window.scrollTo({top:0,behavior:'smooth'})}
function renderHome(){activeModule=-1;document.getElementById('breadcrumb-current').textContent='Overview';document.querySelectorAll('.nav-item').forEach(b=>b.classList.remove('active'));const done=progress.completed.length;const pct=Math.round(done/MODULES.length*100);document.getElementById('page-content').innerHTML=`
 <section class="hero-panel"><div><p class="eyebrow">YOUR FIELD GUIDE TO MAP QUALITY</p><h1>Understand the map.<br>Trust the evidence.</h1><p>Build practical skills in GIS and remote-sensing accuracy assessment through visual lessons, hands-on sampling, calculations and challenges.</p><button class="button" style="background:#fff;color:#0b655f" id="continue-learning">${done?'Continue learning':'Start learning'} <span>→</span></button><div class="hero-stats"><div class="hero-stat"><strong>${done}/${MODULES.length}</strong><span>Modules completed</span></div><div class="hero-stat"><strong>${progress.score||0}</strong><span>Learning points</span></div><div class="hero-stat"><strong>${progress.quizScore||0}/160</strong><span>Assessment score</span></div></div></div><div class="hero-graphic"><svg viewBox="0 0 220 190" fill="none" aria-hidden="true"><path d="M17 36 75 12l58 24 68-20v126l-68 21-58-23-58 21V36Z" stroke="#9edbd0" stroke-width="2"/><path d="m75 12v128m58-104v127M17 80l58-25 58 25 68-20M17 121l58-23 58 22 68-20" stroke="#9edbd0" stroke-opacity=".5"/><circle cx="75" cy="55" r="8" fill="#e9b45c"/><circle cx="133" cy="80" r="8" fill="#6ed0bd"/><circle cx="201" cy="60" r="8" fill="#e9b45c"/><path d="m75 55 58 25 68-20" stroke="#fff" stroke-dasharray="4 5"/></svg></div></section>
 <div class="stat-grid"><div class="stat-card"><div class="stat-label">Course completion</div><div class="stat-value">${pct}%</div><div class="progress-inline" style="margin-top:10px"><span style="width:${pct}%"></span></div></div><div class="stat-card"><div class="stat-label">Your learning points</div><div class="stat-value">${progress.score||0}</div><div class="stat-note">Earn points by completing activities</div></div><div class="stat-card"><div class="stat-label">Class position</div><div class="stat-value" id="home-rank">—</div><div class="stat-note">Based on the available leaderboard</div></div></div>
 <div class="section-heading"><div><h2>Your learning pathway</h2><p>Ten short modules, from core concepts to a final challenge.</p></div><span class="tag">SELF-PACED COURSE</span></div><div class="module-grid">${MODULES.map((m,i)=>`<button class="module-card" data-module="${i}"><span class="module-icon">${m.icon}</span><span><h3>${String(i+1).padStart(2,'0')} · ${m.title}</h3><p>${m.desc}</p><span class="module-meta">${progress.completed.includes(m.id)?'✓ COMPLETED':m.time+' · OPEN MODULE'}</span></span></button>`).join('')}</div>
 <div class="section-heading"><div><h2>Learning outcomes</h2><p>By the end of this course, you should be able to:</p></div></div><div class="three-col"><div class="concept-card"><strong>Design a sample</strong><p>Choose an appropriate sampling strategy and explain its strengths and limitations.</p></div><div class="concept-card"><strong>Interpret an error matrix</strong><p>Distinguish map labels from reference labels and read matrix totals correctly.</p></div><div class="concept-card"><strong>Report map quality</strong><p>Calculate accuracy metrics and communicate uncertainty responsibly.</p></div></div>`;
 document.getElementById('continue-learning').onclick=()=>goToModule(nextModuleIndex());document.querySelectorAll('[data-module]').forEach(b=>b.addEventListener('click',()=>goToModule(Number(b.dataset.module))));refreshHomeRank();}
function nextModuleIndex(){const idx=MODULES.findIndex(m=>!progress.completed.includes(m.id));return idx<0?0:idx}
async function refreshHomeRank(){const rows=await loadLeaderboard();const sorted=[...rows].sort((a,b)=>(b.total_score||0)-(a.total_score||0));const idx=sorted.findIndex(r=>r.student_id===studentId);const el=document.getElementById('home-rank');if(el)el.textContent=idx<0?'—':'#'+(idx+1)}
function renderModule(index){const m=MODULES[index];const page=document.getElementById('page-content');let sections=m.sections.map(s=>`<section class="panel"><h2>${s.heading}</h2><p>${s.body}</p></section>`).join('');let activity='';if(m.id==='intro')activity=introActivity();if(m.id==='accuracy-precision')activity=dartboardActivity();if(m.id==='workflow')activity=workflowActivity();if(m.id==='sampling')activity=samplingActivity();if(m.id==='sample-size')activity=sampleSizeActivity();if(m.id==='sampling-match')activity=samplingMatchActivity();if(m.id==='confusion-matrix')activity=matrixActivity();if(m.id==='metrics')activity=metricsActivity();if(m.id==='practice-lab')activity=mapActivity();if(m.id==='final-quiz')activity=quizActivity();if(m.id==='reflection')activity=reflectionActivity();
 page.innerHTML=`<div class="lesson-header"><div><div class="lesson-number">MODULE ${String(index+1).padStart(2,'0')} / 10 · ${m.time}</div><h1>${m.title}</h1><p>${m.desc}</p></div><div class="lesson-actions"><button class="button button-outline" id="back-home">← Overview</button></div></div>${sections}${activity}<div class="completion-banner"><span>${progress.completed.includes(m.id)?'✓ You have completed this module. You can revisit it anytime.':'Finished exploring this module? Mark it complete to update your course progress.'}</span><button class="button button-primary" id="mark-complete" ${progress.completed.includes(m.id)?'disabled':''}>${progress.completed.includes(m.id)?'Completed ✓':'Mark complete'}</button></div><div class="activity-controls no-print"><button class="button button-outline" id="previous-module" ${index===0?'disabled':''}>← Previous</button><button class="button button-primary" id="next-module">${index===9?'View achievement':'Next module →'}</button></div>`;
 document.getElementById('back-home').onclick=()=>{activeModule=0;renderHome()};document.getElementById('mark-complete').onclick=()=>completeModule(m.id);document.getElementById('previous-module').onclick=()=>goToModule(index-1);document.getElementById('next-module').onclick=()=>goToModule(index===9?9:index+1);
 if(m.id==='accuracy-precision')initDartboard();if(m.id==='sampling')initSampling();if(m.id==='sample-size')document.getElementById('calculate-ss').onclick=calculateSampleSize;if(m.id==='sampling-match')initSamplingMatch();if(m.id==='confusion-matrix')initMatrix();if(m.id==='practice-lab')initMap();if(m.id==='final-quiz')initQuiz();if(m.id==='reflection'){renderLeaderboard();document.getElementById('save-reflection').onclick=saveReflection;document.getElementById('download-certificate').onclick=downloadCertificate;document.getElementById('reflection-text').value=progress.reflection||'';}
}
function completeModule(id){if(!progress.completed.includes(id)){progress.completed.push(id);progress.score=(progress.score||0)+10;saveProgress();buildNavigation();toast('Module completed! 10 learning points added.');renderModule(activeModule)}else toast('This module is already complete.')}
function introActivity(){return `<section class="panel"><span class="tag">THE CORE IDEA</span><h2 style="margin-top:12px">Map label ≠ ground truth</h2><div class="two-col"><div class="concept-card"><strong>Classified map</strong><p>The category assigned by the image classification process: for example, “water”.</p></div><div class="concept-card"><strong>Reference information</strong><p>The best available independent evidence about what was actually present at the sampled location and date.</p></div></div><div class="callout">Accuracy assessment is not simply checking whether a map looks realistic. It is a documented comparison using a defensible sample and appropriate reference information.</div><div class="activity-controls"><button class="button button-secondary" onclick="goToModule(1)">Explore accuracy vs. precision →</button></div></section>`}
function dartboardActivity(){return `<section class="panel"><h2>Try the accuracy & precision target</h2><p>Click the target to place up to 20 observations. Try a tight cluster away from the centre, then a wider cluster around the centre.</p><div class="two-col"><div><canvas id="dart-canvas" width="360" height="360" style="width:min(100%,360px);display:block;margin:auto;border-radius:12px;background:#10283f;cursor:crosshair"></canvas><div class="activity-controls"><button class="button button-outline" id="reset-darts">Reset observations</button><span class="small-note" id="dart-count">0 / 20 observations</span></div></div><div><div class="metric-grid" style="grid-template-columns:1fr 1fr"><div class="metric-tile"><span>Mean distance to centre</span><strong id="dart-accuracy">—</strong></div><div class="metric-tile"><span>Mean spread</span><strong id="dart-precision">—</strong></div></div><div class="callout" id="dart-interpretation">Place at least two observations to compare their distance from the target centre and their spread.</div><p class="small-note">These values are visual teaching indicators only; they are not standard accuracy or precision statistics.</p></div></div></section>`}
function initDartboard(){const canvas=document.getElementById('dart-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');const draw=()=>{ctx.clearRect(0,0,360,360);[145,112,78,44,14].forEach((r,i)=>{ctx.beginPath();ctx.arc(180,180,r,0,Math.PI*2);ctx.fillStyle=i%2?'#31566a':'#1d4055';ctx.fill();ctx.strokeStyle='#9bb7c2';ctx.stroke()});ctx.beginPath();ctx.arc(180,180,7,0,Math.PI*2);ctx.fillStyle='#e7ad4b';ctx.fill();dartPoints.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,5,0,Math.PI*2);ctx.fillStyle='#70d2c0';ctx.fill();ctx.strokeStyle='#fff';ctx.stroke()})};canvas.onclick=e=>{if(dartPoints.length>=20)return;const r=canvas.getBoundingClientRect();dartPoints.push({x:(e.clientX-r.left)*360/r.width,y:(e.clientY-r.top)*360/r.height});draw();updateDartMetrics()};document.getElementById('reset-darts').onclick=()=>{dartPoints=[];draw();updateDartMetrics()};draw()}
function updateDartMetrics(){const n=dartPoints.length;document.getElementById('dart-count').textContent=n+' / 20 observations';if(n<2)return;const meanX=dartPoints.reduce((s,p)=>s+p.x,0)/n,meanY=dartPoints.reduce((s,p)=>s+p.y,0)/n;const dist=dartPoints.reduce((s,p)=>s+Math.hypot(p.x-180,p.y-180),0)/n;const spread=dartPoints.reduce((s,p)=>s+Math.hypot(p.x-meanX,p.y-meanY),0)/n;document.getElementById('dart-accuracy').textContent=dist.toFixed(1)+' px';document.getElementById('dart-precision').textContent=spread.toFixed(1)+' px';document.getElementById('dart-interpretation').textContent=dist<45&&spread<25?'The observations are close to the centre and tightly grouped: high accuracy and high precision in this illustration.':spread<25?'The observations are tightly grouped but away from the centre: precise, but not accurate.':dist<55?'The observations are near the centre on average but spread out: reasonably accurate on average, less precise.':'The observations are spread out and far from the centre: low accuracy and low precision in this illustration.'}
function workflowActivity(){const steps=[['01','Define the map','Document map date, area, class definitions and intended use.'],['02','Design the sample','Choose a probability sampling design and determine sample size.'],['03','Collect reference data','Interpret independent, appropriate-date field or reference observations.'],['04','Compare labels','Record map class and reference class for every sampled unit.'],['05','Build the matrix','Cross-tabulate mapped classes against reference classes.'],['06','Report results','Present OA, class-specific measures, sampling design and limitations.']];return `<section class="panel"><h2>Six stages of a defensible assessment</h2><div class="three-col">${steps.map(s=>`<div class="concept-card"><span class="tag">STEP ${s[0]}</span><strong style="margin-top:10px">${s[1]}</strong><p>${s[2]}</p></div>`).join('')}</div><div class="callout">Good practice: document the reference-data source, acquisition date, interpreter, positional accuracy, sampling unit and any uncertainty in the reference label.</div></section>`}
function samplingActivity(){return `<section class="panel"><h2>Sampling strategy simulator</h2><p>Generate a set of sample locations on this synthetic land-cover grid. Select a strategy and compare how the points are distributed.</p><div class="activity-controls"><div class="field"><label for="sampling-method">Sampling method</label><select id="sampling-method"><option value="random">Simple random</option><option value="systematic">Systematic grid</option><option value="stratified">Stratified by mapped class</option></select></div><div class="field"><label for="sample-count">Number of points</label><input id="sample-count" type="number" min="5" max="50" value="20" style="width:110px"></div><button id="generate-samples" class="button button-primary">Generate sample</button><button id="clear-samples" class="button button-outline">Clear</button></div><div class="two-col" style="margin-top:18px"><div><div id="sampling-grid" class="sample-grid" aria-label="Synthetic land-cover grid"></div><div class="map-legend"><span><i class="legend-dot" style="background:#277c54"></i>Forest</span><span><i class="legend-dot" style="background:#398bc4"></i>Water</span><span><i class="legend-dot" style="background:#a75c50"></i>Built-up</span><span><i class="legend-dot" style="background:#d5b65c"></i>Agriculture</span><span><i class="legend-dot" style="background:#8aaf68"></i>Grassland</span></div></div><div><div class="metric-grid" style="grid-template-columns:1fr 1fr"><div class="metric-tile"><span>Selected locations</span><strong id="sample-selected">0</strong></div><div class="metric-tile"><span>Grid cells</span><strong>100</strong></div></div><div id="sampling-explanation" class="callout">Choose a strategy and generate points. The grid is synthetic and intended for learning.</div></div></div></section>`}
const gridClasses=Array.from({length:100},(_,i)=>{const r=Math.floor(i/10),c=i%10;if((r<2&&c>5)||(r===2&&c>7))return'water';if((r>5&&c<4)||(r===5&&c<2))return'forest';if((r>6&&c>5)||(r===6&&c>7))return'crop';if((r>2&&r<7&&c>3&&c<7))return'urban';return'grass'});let sampledCells=[];
function initSampling(){sampledCells=[];drawSamplingGrid();document.getElementById('generate-samples').onclick=generateSamples;document.getElementById('clear-samples').onclick=()=>{sampledCells=[];drawSamplingGrid();updateSampleStats()};}
function drawSamplingGrid(){const el=document.getElementById('sampling-grid');if(!el)return;el.innerHTML=gridClasses.map((c,i)=>`<button class="sample-cell ${c} ${sampledCells.includes(i)?'sampled selected':''}" title="Cell ${i+1}: ${c}" data-cell="${i}" aria-label="Cell ${i+1}, ${c}"></button>`).join('');el.querySelectorAll('button').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.cell);sampledCells=sampledCells.includes(i)?sampledCells.filter(x=>x!==i):[...sampledCells,i];drawSamplingGrid();updateSampleStats()})}
function generateSamples(){const count=Math.max(5,Math.min(50,Number(document.getElementById('sample-count').value)||20));const method=document.getElementById('sampling-method').value;let picks=[];if(method==='random'){const a=Array.from({length:100},(_,i)=>i).sort(()=>Math.random()-.5);picks=a.slice(0,count)}else if(method==='systematic'){const step=100/count;const start=Math.random()*step;for(let i=0;i<count;i++)picks.push(Math.min(99,Math.floor(start+i*step)))}else{const groups={};gridClasses.forEach((c,i)=>(groups[c]??=[]).push(i));const keys=Object.keys(groups);keys.forEach(k=>{const n=Math.max(1,Math.round(count*groups[k].length/100));picks.push(...groups[k].sort(()=>Math.random()-.5).slice(0,n))});picks=[...new Set(picks)].slice(0,count);while(picks.length<count){const i=Math.floor(Math.random()*100);if(!picks.includes(i))picks.push(i)}}sampledCells=picks;drawSamplingGrid();updateSampleStats();document.getElementById('sampling-explanation').textContent=method==='random'?'Simple random sampling gives each grid cell an equal chance of selection. Clusters can occur by chance.':method==='systematic'?'Systematic sampling selects locations at a regular interval after a random start. Check whether periodic spatial patterns could affect it.':'Stratified sampling selects within each mapped class, helping ensure representation of minority classes. Allocation should be planned and weighted appropriately.'}
function updateSampleStats(){const el=document.getElementById('sample-selected');if(el)el.textContent=sampledCells.length}
function samplingMatchActivity(){return `<section class="panel"><div class="match-heading"><div><span class="tag">SAMPLING KNOWLEDGE CHECK</span><h2>Sampling Methods: Drag & Match</h2><p>Move each statement into the correct category. On a touch screen, tap a statement and then tap the category button.</p></div><div class="match-score"><strong id="sm-score">0 / 8</strong><span id="sm-accuracy">0% correct</span></div></div><div class="match-progress"><span id="sm-progress"></span></div><div id="sm-feedback" class="match-feedback" aria-live="polite">Select a statement to begin.</div><div class="match-layout"><div class="match-source"><h3>Statements</h3><div id="sm-statements"></div></div><div class="match-targets"><div class="match-zone random" data-category="random"><h3>🎲 Random Sampling</h3><p>Selection from the full population, without first allocating a fixed sample to each class.</p><div id="sm-random-items" class="match-placed"></div><button class="button button-outline sm-place" data-category="random">Place selected statement here</button></div><div class="match-zone stratified" data-category="stratified"><h3>▦ Stratified Sampling</h3><p>Random selection is carried out separately within defined strata or mapped classes.</p><div id="sm-stratified-items" class="match-placed"></div><button class="button button-outline sm-place" data-category="stratified">Place selected statement here</button></div></div></div><div class="activity-controls"><button class="button button-outline" id="sm-reset">↻ Reset activity</button></div><div id="sm-complete" class="callout" hidden></div></section>`}
const SM_DATA=[
 {id:1,text:'Points are selected anywhere from the entire study area, with every eligible unit having an equal chance.',cat:'random'},
 {id:2,text:'Points are selected randomly but separately within each land-cover class.',cat:'stratified'},
 {id:3,text:'The number of selected points in each class may vary according to how often that class occurs in the population.',cat:'random'},
 {id:4,text:'A minimum or planned number of samples can be assigned to every class, including rare classes.',cat:'stratified'},
 {id:5,text:'A rare land-cover class may receive very few samples, or none, by chance.',cat:'random'},
 {id:6,text:'It can improve representation of minority classes by sampling within each class.',cat:'stratified'},
 {id:7,text:'It is generally simpler to implement because the sample is drawn from one population frame.',cat:'random'},
 {id:8,text:'It requires class/stratum information and may require weights when estimating map-wide accuracy.',cat:'stratified'}
];
let smItems=[],smSelected=null,smAttempts=0,smCorrect=0;
function initSamplingMatch(){smItems=SM_DATA.map(x=>({...x,matched:false})).sort(()=>Math.random()-.5);smSelected=null;smAttempts=0;smCorrect=0;drawSamplingMatch();document.getElementById('sm-reset').onclick=initSamplingMatch;document.querySelectorAll('.sm-place').forEach(b=>b.onclick=()=>placeSamplingMatch(b.dataset.category));}
function drawSamplingMatch(){const list=document.getElementById('sm-statements');if(!list)return;list.innerHTML=smItems.filter(x=>!x.matched).map((x,i)=>`<button class="match-statement ${smSelected===x.id?'chosen':''}" draggable="true" data-id="${x.id}"><span class="match-number">${i+1}</span><span>${x.text}</span><span class="match-grip">⠿</span></button>`).join('');list.querySelectorAll('.match-statement').forEach(b=>{b.onclick=()=>{smSelected=Number(b.dataset.id);drawSamplingMatch()};b.ondragstart=e=>{smSelected=Number(b.dataset.id);e.dataTransfer.setData('text/plain',b.dataset.id);e.dataTransfer.effectAllowed='move'};});document.querySelectorAll('.match-zone').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('drag-over')};z.ondragleave=()=>z.classList.remove('drag-over');z.ondrop=e=>{e.preventDefault();z.classList.remove('drag-over');smSelected=Number(e.dataTransfer.getData('text/plain'))||smSelected;placeSamplingMatch(z.dataset.category)}});['random','stratified'].forEach(cat=>{const target=document.getElementById('sm-'+cat+'-items');target.innerHTML=smItems.filter(x=>x.matched&&x.cat===cat).map(x=>`<div class="match-placed-item">✓ ${x.text}</div>`).join('')});const score=document.getElementById('sm-score');if(score)score.textContent=`${smCorrect} / 8`;const accuracy=document.getElementById('sm-accuracy');if(accuracy)accuracy.textContent=`${smAttempts?Math.round(smCorrect/smAttempts*100):0}% correct`;const progress=document.getElementById('sm-progress');if(progress)progress.style.width=(smCorrect/8*100)+'%';const fb=document.getElementById('sm-feedback');if(fb)fb.textContent=smSelected?'Statement selected. Choose a category to place it.':'Select a statement to begin.';const done=document.getElementById('sm-complete');if(done&&smCorrect===8){done.hidden=false;done.textContent=`Excellent! You matched all eight statements in ${smAttempts} attempts.`}else if(done)done.hidden=true;}
function placeSamplingMatch(category){if(!smSelected)return;const item=smItems.find(x=>x.id===smSelected);if(!item||item.matched)return;smAttempts++;const fb=document.getElementById('sm-feedback');if(item.cat===category){item.matched=true;smCorrect++;smSelected=null;if(fb)fb.textContent='Correct! That statement describes '+(category==='random'?'random sampling.':'stratified sampling.')}else{smSelected=null;}drawSamplingMatch();if(fb&&item.cat!==category)fb.textContent='Not quite. Try again: consider whether points are drawn from the whole population or separately within classes.';if(fb&&item.cat===category)fb.textContent='Correct! That statement describes '+(category==='random'?'random sampling.':'stratified sampling.');}

function sampleSizeActivity(){return `<section class="panel"><h2>Proportion sample-size calculator</h2><p>Estimate the sample size needed to estimate a proportion under a simple random sampling assumption.</p><div class="two-col"><div class="concept-card"><div class="field"><label for="ss-z">Z value (95% confidence = 1.96)</label><input id="ss-z" type="number" step="0.01" value="1.96"></div><div class="field" style="margin-top:12px"><label for="ss-p">Expected accuracy / proportion (p)</label><input id="ss-p" type="number" min="0.01" max="0.99" step="0.01" value="0.85"></div><div class="field" style="margin-top:12px"><label for="ss-e">Margin of error (E)</label><input id="ss-e" type="number" min="0.001" max="0.5" step="0.005" value="0.05"></div><button id="calculate-ss" class="button button-primary" style="margin-top:15px">Calculate sample size</button></div><div class="metric-tile" style="display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center"><span>Required sample size (n)</span><strong id="ss-result" style="font-size:48px">196</strong><p style="color:#c4d6dd;font-size:10px">Rounded up to the next whole observation</p></div></div><div class="formula">n = Z² × p × (1 − p) / E²</div><div id="ss-worked" class="callout">n = 1.96² × 0.85 × 0.15 / 0.05² = 195.92, so round up to 196.</div></section>`}
function calculateSampleSize(){const z=Number(document.getElementById('ss-z').value),p=Number(document.getElementById('ss-p').value),e=Number(document.getElementById('ss-e').value);if(!(z>0&&p>0&&p<1&&e>0&&e<1)){toast('Enter Z > 0, p between 0 and 1, and E between 0 and 1.');return}const raw=z*z*p*(1-p)/(e*e),n=Math.ceil(raw);document.getElementById('ss-result').textContent=n.toLocaleString();document.getElementById('ss-worked').textContent=`n = ${z}² × ${p} × (1 − ${p}) / ${e}² = ${raw.toFixed(2)}. Round up to ${n}. Remember: this is a simple starting estimate, not a complete design for every accuracy assessment.`}

/* --- Map-based accuracy assessment simulator ---
   Matrix convention: rows = classified map labels; columns = reference labels.
   This teaching simulator reports raw sample proportions. Stratified samples
   are not area-adjusted; a real stratified accuracy estimate may require weights.
*/
const aaClasses = ['forest','water','urban','agriculture','grassland'];
const aaNames = ['Forest','Water Bodies','Urban Areas','Agriculture','Grassland'];
const aaColors = {
  forest:'#059669', water:'#2563eb', urban:'#dc2626',
  agriculture:'#ca8a04', grassland:'#65a30d'
};
let aaReferenceGrid = [];
let aaClassifiedGrid = [];
let aaSampled = new Set();
const aaGridSize = 15;

function matrixActivity(){
  return `<section class="panel aa-lab" id="accuracy-simulator">
    <div class="aa-heading">
      <div><span class="tag">LEARNING GIS</span><h2>Map-based Accuracy Assessment Simulator</h2>
      <p>Choose validation locations, compare the classified map with reference data, and watch the error matrix and accuracy measures update.</p></div>
      <div class="aa-live-pill"><span></span> Live calculation</div>
    </div>
    <div class="aa-instructions"><strong>How to use this simulator</strong><ol>
      <li>Inspect the two maps. The left map shows the automated classification; the right map shows the reference land cover.</li>
      <li>Select sample locations by clicking cells on the classified map, or choose a sampling strategy.</li>
      <li>Review the confusion matrix and the accuracy calculations generated from the selected samples.</li>
    </ol></div>
    <div class="aa-top-grid">
      <article class="aa-card aa-map-card"><div class="aa-card-head"><div><span class="aa-step">01 · MAP OUTPUT</span><h3>Classified Map</h3><p>Click any cell to add or remove a validation sample.</p></div><span class="aa-map-icon">▦</span></div><div class="aa-grid-wrap"><div id="aa-classified-map" class="aa-map-grid" aria-label="Clickable classified land cover map"></div></div><div class="aa-map-foot"><span class="aa-key"><i class="aa-sample-key">✓</i> Selected sample</span><span class="aa-key">15 × 15 cells</span></div></article>
      <article class="aa-card aa-map-card"><div class="aa-card-head"><div><span class="aa-step">02 · REFERENCE DATA</span><h3>Ground Truth</h3><p>Reference land cover from field validation (simulated).</p></div><span class="aa-map-icon">⌖</span></div><div class="aa-grid-wrap"><div id="aa-reference-map" class="aa-map-grid" aria-label="Reference land cover map"></div></div><div class="aa-map-foot"><span class="aa-key">Independent reference labels</span><span class="aa-key">Same locations</span></div></article>
      <article class="aa-card aa-control-card"><div class="aa-sample-count"><span class="aa-step">03 · VALIDATION SAMPLE</span><div class="aa-count-number" id="aa-sample-count">0</div><strong>Samples collected</strong><p>Choose a strategy or click cells on the classified map.</p></div>
        <div class="aa-legend"><h3>Land-cover classes</h3><div class="aa-legend-list">${aaNames.map((n,i)=>`<span><i style="background:${aaColors[aaClasses[i]]}"></i>${n}</span>`).join('')}</div></div>
        <div class="aa-strategies"><h3>Sampling strategies</h3>
          <button type="button" data-aa-action="random10">Random sampling <b>n = 10</b></button>
          <button type="button" data-aa-action="random30">Random sampling <b>n = 30</b></button>
          <button type="button" data-aa-action="random50">Random sampling <b>n = 50</b></button>
          <button type="button" data-aa-action="stratified">Stratified random <b>10 / class</b></button>
          <button type="button" data-aa-action="systematic">Systematic grid (random start)</button>
          <div class="aa-button-row"><button type="button" data-aa-action="clear" class="secondary">Clear samples</button><button type="button" data-aa-action="reset" class="danger">New maps ↻</button></div>
        </div>
      </article>
    </div>
    <section class="aa-card aa-overall"><div><span class="aa-step">04 · FIRST RESULT</span><h3>Overall Accuracy</h3><p>Percentage of sampled locations where the map label matches the reference label.</p></div><div class="aa-overall-value" id="aa-overall">—<small>%</small></div><div class="aa-progress"><span id="aa-overall-bar"></span></div><div class="aa-overall-note" id="aa-overall-note">Collect samples to calculate overall accuracy.</div></section>
    <div class="aa-results-grid">
      <section class="aa-card"><div class="aa-card-head"><div><span class="aa-step">05 · ERROR MATRIX</span><h3>Confusion Matrix</h3><p>Rows represent classified map labels; columns represent reference labels.</p></div></div><div class="aa-table-wrap"><table class="aa-matrix" id="aa-matrix"><thead></thead><tbody></tbody></table></div><div class="aa-matrix-note"><span><i class="aa-diagonal-key"></i> Correct classification (diagonal)</span><span><i class="aa-error-key"></i> Misclassification (off-diagonal)</span></div></section>
      <section class="aa-card aa-metric-panel"><div class="aa-card-head"><div><span class="aa-step">06 · CLASS-LEVEL RESULTS</span><h3>Producer's Accuracy</h3><p>How well reference locations of each class were captured by the map. Related to omission error.</p></div></div><div id="aa-producer" class="aa-bars"><p class="aa-empty">No samples yet.</p></div><div class="aa-metric-divider"></div><div class="aa-card-head"><div><h3>User's Accuracy</h3><p>How reliable each mapped class is. Related to commission error.</p></div></div><div id="aa-user" class="aa-bars"><p class="aa-empty">No samples yet.</p></div></section>
    </div>
    <section class="aa-card aa-kappa"><div><span class="aa-step">07 · AGREEMENT BEYOND CHANCE</span><h3>Kappa Coefficient (κ)</h3><p>Measures observed agreement after accounting for the agreement expected from the row and column totals.</p></div><strong id="aa-kappa">—</strong><div class="aa-kappa-scale"><span>Below 0</span><span>0.40</span><span>0.60</span><span>0.80</span><span>1.00</span></div><div class="aa-kappa-track"><i></i><i></i><i></i><i></i></div><p id="aa-kappa-note">Collect samples to calculate Kappa.</p></section>
    <section class="aa-card aa-worked"><div class="aa-card-head"><div><span class="aa-step">08 · LEARN THE MATHEMATICS</span><h3>Step-by-step calculation breakdown</h3><p>These equations update using your selected samples. Expand each section to see how the result is calculated.</p></div></div><div id="aa-calculation-steps"><p class="aa-empty">Select at least one sample to reveal the calculations.</p></div></section>
    <div class="aa-disclaimer"><strong>Learning data notice:</strong> Both maps are generated synthetic examples, not actual satellite imagery or field observations. The displayed results demonstrate the mechanics of accuracy assessment. The raw sample Overall Accuracy is not an area-adjusted estimate for unequal stratified sampling; a real study may need sampling-design weights.</div>
  </section>`;
}

function initMatrix(){
  const root=document.getElementById('accuracy-simulator');
  if(!root)return;
  root.addEventListener('click',e=>{
    const action=e.target.closest('[data-aa-action]')?.dataset.aaAction;
    if(action==='random10')aaSampleRandom(10);
    if(action==='random30')aaSampleRandom(30);
    if(action==='random50')aaSampleRandom(50);
    if(action==='stratified')aaSampleStratified();
    if(action==='systematic')aaSampleSystematic();
    if(action==='clear'){aaSampled.clear();aaUpdateDisplay()}
    if(action==='reset')aaInitialize();
    const cell=e.target.closest('[data-aa-cell]');
    if(cell){const key=cell.dataset.aaCell;if(aaSampled.has(key))aaSampled.delete(key);else aaSampled.add(key);aaUpdateDisplay()}
  });
  aaInitialize();
}

function aaInitialize(){
  aaReferenceGrid=[];aaClassifiedGrid=[];aaSampled.clear();
  for(let r=0;r<aaGridSize;r++){
    aaReferenceGrid[r]=[];aaClassifiedGrid[r]=[];
    for(let c=0;c<aaGridSize;c++){
      let idx;
      if(r<5&&c<5)idx=Math.random()<.7?0:Math.floor(Math.random()*5);
      else if(r>10&&c>10)idx=Math.random()<.6?2:Math.floor(Math.random()*5);
      else if(Math.abs(r-7)<2||Math.abs(c-7)<2)idx=Math.random()<.5?1:Math.floor(Math.random()*5);
      else idx=Math.floor(Math.random()*5);
      const ref=aaClasses[idx];aaReferenceGrid[r][c]=ref;
      if(Math.random()<.8)aaClassifiedGrid[r][c]=ref;
      else{
        const alternatives={
          forest:['grassland','agriculture'],grassland:['forest','agriculture'],
          agriculture:['grassland','forest'],urban:aaClasses.filter(x=>x!=='urban'),
          water:aaClasses.filter(x=>x!=='water')
        };
        const options=alternatives[ref];aaClassifiedGrid[r][c]=options[Math.floor(Math.random()*options.length)];
      }
    }
  }
  aaUpdateDisplay();
}

function aaRenderMap(grid,id,clickable){
  const el=document.getElementById(id);if(!el)return;
  el.innerHTML='';
  for(let r=0;r<aaGridSize;r++)for(let c=0;c<aaGridSize;c++){
    const cell=document.createElement('button');cell.type='button';
    cell.className='aa-cell'+(clickable&&aaSampled.has(`${r},${c}`)?' selected':'');
    cell.style.background=aaColors[grid[r][c]];
    cell.title=`Row ${r+1}, column ${c+1}: ${aaNames[aaClasses.indexOf(grid[r][c])]}`;
    if(clickable){cell.dataset.aaCell=`${r},${c}`;cell.setAttribute('aria-label',`Select row ${r+1}, column ${c+1}`)}
    else{cell.tabIndex=-1;cell.disabled=true}
    el.appendChild(cell);
  }
}

function aaSampleRandom(n){
  const all=Array.from({length:aaGridSize*aaGridSize},(_,i)=>`${Math.floor(i/aaGridSize)},${i%aaGridSize}`);
  for(let i=all.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[all[i],all[j]]=[all[j],all[i]]}
  aaSampled=new Set(all.slice(0,n));aaUpdateDisplay();
}
function aaSampleStratified(){
  const chosen=[];
  aaClasses.forEach(cls=>{
    const cells=[];
    for(let r=0;r<aaGridSize;r++)for(let c=0;c<aaGridSize;c++)if(aaClassifiedGrid[r][c]===cls)cells.push(`${r},${c}`);
    for(let i=cells.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cells[i],cells[j]]=[cells[j],cells[i]]}
    chosen.push(...cells.slice(0,Math.min(10,cells.length)));
  });
  aaSampled=new Set(chosen);aaUpdateDisplay();
}
function aaSampleSystematic(){
  aaSampled=new Set();
  const step=3;
  // Choose a random row and column start within the interval, then sample at a fixed grid interval.
  const startRow=Math.floor(Math.random()*step);
  const startCol=Math.floor(Math.random()*step);
  for(let r=startRow;r<aaGridSize;r+=step)for(let c=startCol;c<aaGridSize;c+=step)aaSampled.add(`${r},${c}`);
  aaUpdateDisplay();
}

function aaCalculate(){
  if(!aaSampled.size)return null;
  const matrix=aaClasses.map(()=>aaClasses.map(()=>0));
  let correct=0;
  aaSampled.forEach(key=>{
    const [r,c]=key.split(',').map(Number);
    const mapIdx=aaClasses.indexOf(aaClassifiedGrid[r][c]);
    const refIdx=aaClasses.indexOf(aaReferenceGrid[r][c]);
    matrix[mapIdx][refIdx]++;
    if(mapIdx===refIdx)correct++;
  });
  const n=aaSampled.size;
  const rows=matrix.map(row=>row.reduce((a,b)=>a+b,0));
  const cols=aaClasses.map((_,c)=>matrix.reduce((sum,row)=>sum+row[c],0));
  const oa=correct/n;
  const pa=aaClasses.map((_,i)=>cols[i]?matrix[i][i]/cols[i]:null);
  const ua=aaClasses.map((_,i)=>rows[i]?matrix[i][i]/rows[i]:null);
  const pe=rows.reduce((sum,row,i)=>sum+(row/n)*(cols[i]/n),0);
  const kappa=(1-pe)!==0?(oa-pe)/(1-pe):null;
  return {matrix,n,correct,rows,cols,oa,pa,ua,pe,kappa};
}
function aaPct(v){return v===null?'N/A':(v*100).toFixed(1)+'%'}
function aaUpdateDisplay(){
  aaRenderMap(aaClassifiedGrid,'aa-classified-map',true);
  aaRenderMap(aaReferenceGrid,'aa-reference-map',false);
  const count=document.getElementById('aa-sample-count');if(count)count.textContent=aaSampled.size;
  const result=aaCalculate();
  const overall=document.getElementById('aa-overall'),bar=document.getElementById('aa-overall-bar'),note=document.getElementById('aa-overall-note');
  if(!result){
    if(overall)overall.innerHTML='—<small>%</small>';if(bar)bar.style.width='0%';
    if(note)note.textContent='Collect samples to calculate overall accuracy.';
    ['aa-producer','aa-user'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML='<p class="aa-empty">No samples yet.</p>'});
    const matrix=document.getElementById('aa-matrix');if(matrix){matrix.querySelector('thead').innerHTML='';matrix.querySelector('tbody').innerHTML='<tr><td colspan="7" class="aa-empty">Collect samples to generate the confusion matrix.</td></tr>'}
    const k=document.getElementById('aa-kappa');if(k)k.textContent='—';
    const kn=document.getElementById('aa-kappa-note');if(kn)kn.textContent='Collect samples to calculate Kappa.';
    const steps=document.getElementById('aa-calculation-steps');if(steps)steps.innerHTML='<p class="aa-empty">Select at least one sample to reveal the calculations.</p>';
    return;
  }
  overall.innerHTML=`${(result.oa*100).toFixed(1)}<small>%</small>`;bar.style.width=(result.oa*100)+'%';
  note.textContent=`${result.correct} of ${result.n} sampled locations were correctly classified.`;
  const matrix=document.getElementById('aa-matrix');
  matrix.querySelector('thead').innerHTML=`<tr><th>Map ↓ / Reference →</th>${aaNames.map(n=>`<th>${n}</th>`).join('')}<th>Map total</th></tr>`;
  matrix.querySelector('tbody').innerHTML=aaNames.map((name,r)=>`<tr><th>${name}</th>${aaNames.map((_,c)=>`<td class="${r===c?'correct-cell':'error-cell'}">${result.matrix[r][c]}</td>`).join('')}<td class="total-cell">${result.rows[r]}</td></tr>`).join('')+
    `<tr class="totals-row"><th>Reference total</th>${result.cols.map(v=>`<td>${v}</td>`).join('')}<td>${result.n}</td></tr>`;
  const renderBars=(id,values,errors)=>{
    const el=document.getElementById(id);
    el.innerHTML=aaNames.map((name,i)=>{
      const val=values[i],err=errors[i];
      return `<div class="aa-bar-item"><div class="aa-bar-head"><strong>${name}</strong><b>${aaPct(val)}</b></div><div class="aa-bar-track"><span style="width:${val===null?0:val*100}%;background:${aaColors[aaClasses[i]]}"></span></div><small>${err===null?'Error: N/A':`Error: ${(err*100).toFixed(1)}%`}</small></div>`;
    }).join('');
  };
  renderBars('aa-producer',result.pa,result.pa.map(v=>v===null?null:1-v));
  renderBars('aa-user',result.ua,result.ua.map(v=>v===null?null:1-v));
  const k=document.getElementById('aa-kappa');k.textContent=result.kappa===null?'N/A':result.kappa.toFixed(3);
  const kn=document.getElementById('aa-kappa-note');kn.textContent=result.kappa===null?'Kappa is undefined for these margins.':`Observed agreement Po = ${result.oa.toFixed(3)}; expected agreement Pe = ${result.pe.toFixed(3)}.`;
  aaRenderCalculationSteps(result);
}

function aaRenderCalculationSteps(x){
  const el=document.getElementById('aa-calculation-steps');if(!el)return;
  const rowTerms=x.rows.map((v,i)=>`(${v}/${x.n}) × (${x.cols[i]}/${x.n})`).join(' + ');
  el.innerHTML=`
  <details class="aa-step-detail" open><summary>1. Overall Accuracy (OA)</summary><div class="aa-step-body"><p><b>Meaning:</b> the proportion of all sampled locations where the classified label agrees with the reference label.</p><div class="aa-equation">OA = (sum of diagonal values ÷ total samples) × 100</div><div class="aa-equation">${x.correct} ÷ ${x.n} × 100 = <b>${(x.oa*100).toFixed(2)}%</b></div><p>${x.correct} diagonal observations were correct out of ${x.n} total observations.</p></div></details>
  <details class="aa-step-detail"><summary>2. Producer's Accuracy (PA) and Omission Error</summary><div class="aa-step-body"><p><b>Meaning:</b> for each reference class, what proportion was correctly identified on the map? Use the reference (column) total.</p>${aaNames.map((name,i)=>`<div class="aa-equation"><b>${name}:</b> PA = ${x.matrix[i][i]} ÷ ${x.cols[i]} × 100 = <b>${aaPct(x.pa[i])}</b>; Omission error = 100% − PA = <b>${x.pa[i]===null?'N/A':((1-x.pa[i])*100).toFixed(1)+'%'}</b></div>`).join('')}</div></details>
  <details class="aa-step-detail"><summary>3. User's Accuracy (UA) and Commission Error</summary><div class="aa-step-body"><p><b>Meaning:</b> among locations mapped as a class, what proportion truly belongs to that class? Use the map (row) total.</p>${aaNames.map((name,i)=>`<div class="aa-equation"><b>${name}:</b> UA = ${x.matrix[i][i]} ÷ ${x.rows[i]} × 100 = <b>${aaPct(x.ua[i])}</b>; Commission error = 100% − UA = <b>${x.ua[i]===null?'N/A':((1-x.ua[i])*100).toFixed(1)+'%'}</b></div>`).join('')}</div></details>
  <details class="aa-step-detail"><summary>4. Kappa coefficient (κ)</summary><div class="aa-step-body"><p><b>Step A — Observed agreement:</b> Po = diagonal sum ÷ N = ${x.correct} ÷ ${x.n} = <b>${x.oa.toFixed(4)}</b>.</p><p><b>Step B — Expected agreement:</b> Pe = Σ (row totalᵢ ÷ N) × (column totalᵢ ÷ N).</p><div class="aa-equation">Pe = ${rowTerms} = <b>${x.pe.toFixed(4)}</b></div><p><b>Step C — Kappa:</b> κ = (Po − Pe) ÷ (1 − Pe)</p><div class="aa-equation">κ = (${x.oa.toFixed(4)} − ${x.pe.toFixed(4)}) ÷ (1 − ${x.pe.toFixed(4)}) = <b>${x.kappa===null?'N/A':x.kappa.toFixed(4)}</b></div></div></details>`;
}
function metricsActivity(){return `<section class="panel"><h2>Formula and interpretation guide</h2><div class="two-col"><div class="concept-card"><span class="tag">OVERALL ACCURACY</span><div class="formula">OA = Σ diagonal / N × 100</div><p>Share of all sampled locations correctly classified.</p></div><div class="concept-card"><span class="tag">PRODUCER’S ACCURACY</span><div class="formula">PAᵢ = nᵢᵢ / column totalᵢ × 100</div><p>How well the map captures a reference class. 1 − PA is omission error.</p></div><div class="concept-card"><span class="tag">USER’S ACCURACY</span><div class="formula">UAᵢ = nᵢᵢ / row totalᵢ × 100</div><p>Reliability of a mapped class. 1 − UA is commission error.</p></div><div class="concept-card"><span class="tag">KAPPA</span><div class="formula">κ = (Pₒ − Pₑ) / (1 − Pₑ)</div><p>Agreement adjusted for expected agreement from the matrix margins.</p></div></div><div class="callout"><strong>Interpretation example:</strong> if 36 of 40 reference-forest samples are mapped as forest, producer’s accuracy for forest is 36/40 = 90%. If 36 of 45 map-forest samples are actually reference forest, user’s accuracy is 36/45 = 80%.</div><div class="activity-controls"><button class="button button-secondary" onclick="goToModule(6)">Practice with the confusion matrix →</button></div></section>`}
function mapActivity(){return `<section class="panel"><h2>Illustrative satellite map & reference checks</h2><p>Switch between an imagery basemap and a street basemap. Click a sample marker to inspect the teaching example.</p><div id="practice-map" class="map-box"></div><div class="map-legend"><span><i class="legend-dot" style="background:#16a085"></i>Agreement example</span><span><i class="legend-dot" style="background:#d65d4c"></i>Disagreement example</span></div><div id="map-detail" class="callout">Select a marker to see its mapped and reference labels.</div><p class="small-note">Basemap tiles are provided by Esri / OpenStreetMap and require an internet connection. Sample labels are synthetic and are not field observations.</p></section>`}
function initMap(){if(!window.L){document.getElementById('practice-map').innerHTML='<div class="empty-state">The interactive map library could not load. Check your internet connection.</div>';return}if(mapInstance){mapInstance.remove();mapInstance=null}const map=L.map('practice-map').setView([41.6528,-83.5379],12);mapInstance=map;const imagery=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri'});const streets=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'});imagery.addTo(map);L.control.layers({'Satellite imagery':imagery,'Street map':streets}).addTo(map);const pts=[{xy:[41.66,-83.56],map:'Vegetation',ref:'Vegetation',ok:true},{xy:[41.65,-83.52],map:'Built-up',ref:'Bare land',ok:false},{xy:[41.64,-83.54],map:'Water',ref:'Water',ok:true},{xy:[41.67,-83.50],map:'Agriculture',ref:'Vegetation',ok:false},{xy:[41.63,-83.57],map:'Built-up',ref:'Built-up',ok:true}];pts.forEach((p,i)=>{const marker=L.circleMarker(p.xy,{radius:8,color:'#fff',weight:2,fillColor:p.ok?'#16a085':'#d65d4c',fillOpacity:.95}).addTo(map);marker.on('click',()=>{document.getElementById('map-detail').textContent=`Sample ${i+1}: Map label = ${p.map}; reference label = ${p.ref}. ${p.ok?'Agreement: the labels match.':'Disagreement: the labels differ.'}`})});setTimeout(()=>map.invalidateSize(),150)}
function quizActivity(){return `<section class="panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><h2>Course assessment</h2><p>16 questions · 10 points each · 12-minute time limit.</p></div><div class="timer" id="quiz-timer">12:00</div></div><div id="quiz-area"></div><div class="activity-controls"><button class="button button-primary" id="submit-quiz">Submit quiz</button><button class="button button-outline" id="restart-quiz">Restart timer</button></div><div id="quiz-result" style="margin-top:15px"></div></section>`}
function initQuiz(){const restart=document.getElementById('restart-quiz');restart.onclick=()=>{if(quizState?.interval)clearInterval(quizState.interval);progress.quizAnswers={};quizState=null;initQuiz()};if(progress.quizAnswers&&Object.keys(progress.quizAnswers).length===QUIZ.length){showQuizReview(progress.quizAnswers,progress.quizScore);return}quizState={answers:{},seconds:720,submitted:false};drawQuiz();quizState.interval=setInterval(()=>{if(!quizState||quizState.submitted)return;quizState.seconds--;const el=document.getElementById('quiz-timer');if(el)el.textContent=String(Math.floor(quizState.seconds/60)).padStart(2,'0')+':'+String(quizState.seconds%60).padStart(2,'0');if(quizState.seconds<=0)submitQuiz()},1000);document.getElementById('submit-quiz').onclick=submitQuiz}
function drawQuiz(){const el=document.getElementById('quiz-area');el.innerHTML=QUIZ.map((q,i)=>`<div class="quiz-question"><h3>${i+1}. ${q.q}</h3><div class="option-list">${q.o.map((o,j)=>`<button class="quiz-option" data-q="${i}" data-a="${j}">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}</div></div>`).join('');el.querySelectorAll('.quiz-option').forEach(b=>b.onclick=()=>{if(!quizState||quizState.submitted)return;quizState.answers[b.dataset.q]=Number(b.dataset.a);el.querySelectorAll(`[data-q="${b.dataset.q}"]`).forEach(x=>x.classList.toggle('selected',x===b));b.style.borderColor='#0d8b83';b.style.background='#edf8f5'})}
function submitQuiz(){if(!quizState||quizState.submitted)return;quizState.submitted=true;clearInterval(quizState.interval);let score=0;QUIZ.forEach((q,i)=>{if(quizState.answers[i]===q.a)score+=10});progress.quizAnswers={...quizState.answers};const previousBest=progress.quizScore||0;if(score>previousBest)progress.score=(progress.score||0)+(score-previousBest);progress.quizScore=Math.max(previousBest,score);saveProgress();document.getElementById('submit-quiz').disabled=true;showQuizReview(quizState.answers,score);if(score>=120&&!progress.completed.includes('final-quiz')){progress.completed.push('final-quiz');progress.score+=10;saveProgress();buildNavigation()}toast(`Assessment submitted: ${score}/160 points.`)}
function showQuizReview(answers,score){const el=document.getElementById('quiz-area');el.innerHTML=QUIZ.map((q,i)=>{const a=answers[i];return `<div class="quiz-question"><h3>${i+1}. ${q.q}</h3><div class="option-list">${q.o.map((o,j)=>`<div class="quiz-option ${j===q.a?'correct':a===j&&j!==q.a?'incorrect':''}">${String.fromCharCode(65+j)}. ${o} ${j===q.a?'✓':''}</div>`).join('')}</div><div class="feedback">${q.e}</div></div>`}).join('');const res=document.getElementById('quiz-result');res.innerHTML=`<div class="completion-banner"><strong>Your result: ${score}/160 (${(score/160*100).toFixed(0)}%)</strong><span>${score>=120?'Pass — well done!':'Review the explanations and try again.'}</span></div>`;const timer=document.getElementById('quiz-timer');if(timer)timer.textContent='SUBMITTED';const submit=document.getElementById('submit-quiz');if(submit)submit.disabled=true}
function reflectionActivity(){return `<section class="panel"><h2>Course reflection</h2><p>In a few sentences, explain one thing you learned and one issue you would check before trusting a land-cover accuracy result.</p><div class="field"><label for="reflection-text">Your reflection</label><textarea id="reflection-text" rows="4" placeholder="I learned that…"></textarea></div><div class="activity-controls"><button class="button button-primary" id="save-reflection">Save reflection</button><button class="button button-outline" id="download-certificate">Download certificate / Print PDF</button></div><p class="small-note">Certificate eligibility: complete all course modules and achieve at least 120/160 on the assessment. Use your browser’s print dialog and choose “Save as PDF”.</p></section><section class="panel"><div class="section-heading" style="margin:0 0 12px"><div><h2>Leaderboard on this device</h2><p>Scores saved in this browser on this device.</p></div><button class="button button-outline" id="refresh-leaderboard">Refresh</button></div><div id="leaderboard-list"><div class="empty-state">Loading leaderboard…</div></div><p class="small-note" id="leaderboard-note"></p></section><section class="panel"><h2>Certificate preview</h2><div id="certificate-preview"></div><div class="activity-controls certificate-actions no-print"><button class="button button-primary" id="download-certificate-2">Print / Save certificate as PDF</button></div></section>`}
async function renderLeaderboard(){const rows=await loadLeaderboard();const el=document.getElementById('leaderboard-list');if(!el)return;const sorted=[...rows].sort((a,b)=>(b.total_score||0)-(a.total_score||0));el.innerHTML=sorted.length?sorted.slice(0,20).map((r,i)=>`<div class="leaderboard-row"><span class="rank-badge">${i+1}</span><strong>${escapeHTML(r.student_name||'Learner')} ${r.student_id===studentId?'<span class="tag">YOU</span>':''}</strong><span style="text-align:right;font-weight:800;color:#0d8b83">${r.total_score||0} pts</span></div>`).join(''):'<div class="empty-state">No classroom scores yet. Complete a learning activity to appear here.</div>';const note=document.getElementById('leaderboard-note');if(note)note.textContent='This leaderboard includes learners who have used this website in this browser on this device. GitHub Pages does not provide a shared database.';const preview=document.getElementById('certificate-preview');if(preview)preview.innerHTML=certificateHTML(false);const refresh=document.getElementById('refresh-leaderboard');if(refresh)refresh.onclick=renderLeaderboard;const cert2=document.getElementById('download-certificate-2');if(cert2)cert2.onclick=downloadCertificate}
function saveReflection(){progress.reflection=document.getElementById('reflection-text').value.trim();localStorage.setItem('gis_lab_progress_'+studentId,JSON.stringify(progress));toast('Reflection saved on this device.')}
function certificateEligible(){return progress.completed.length===MODULES.length&&progress.quizScore>=120}
function certificateHTML(printable=true){const eligible=certificateEligible();return `<div class="certificate"><div class="cert-brand">LEARNING GIS · ACCURACY ASSESSMENT</div><h2>Certificate of Completion</h2><p>This certificate is proudly presented to</p><div class="cert-name">${escapeHTML(studentName)}</div><p>for completing the learning course in</p><h3 style="font:800 21px Manrope;color:#0d7770">GIS Accuracy Assessment</h3><p style="max-width:490px;margin:14px auto;color:#6d7d89">Demonstrating engagement with sampling strategies, confusion matrices, accuracy metrics, reference data and map validation.</p><div class="certificate-seal">✦</div><p style="font-size:11px;color:#8b7952;margin-top:18px">${new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'})} · ${eligible?'COURSE REQUIREMENTS COMPLETED':'PREVIEW — COMPLETE ALL MODULES AND SCORE AT LEAST 120/160 TO EARN'}</p></div>`}
function downloadCertificate(){if(!certificateEligible()){toast('Certificate not yet unlocked. Complete all course modules and score at least 120/160 on the assessment.');return}const win=window.open('','_blank');if(!win){toast('Allow pop-ups for this site to print your certificate.');return}win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>GIS Accuracy Assessment Certificate</title><style>body{font-family:Arial,sans-serif;margin:0;padding:35px;background:#f7f7f4;color:#263c4b}.certificate{background:#fff;border:9px double #b99b57;padding:55px 35px;text-align:center;max-width:850px;margin:20px auto;min-height:560px;display:flex;flex-direction:column;justify-content:center}.cert-brand{font-weight:800;letter-spacing:.2em;color:#0d8b83;font-size:12px}.certificate h2{font-size:42px;margin:30px 0 8px}.cert-name{font-size:34px;font-weight:700;color:#0b7770;border-bottom:1px solid #d6c69e;display:inline-block;padding:10px 35px;margin:14px auto}.certificate-seal{width:70px;height:70px;border:2px solid #b99b57;border-radius:50%;display:grid;place-items:center;margin:25px auto;color:#9c7c39;font-size:26px}@page{size:landscape;margin:12mm}@media print{body{background:#fff;padding:0}.certificate{margin:0 auto;max-width:none;min-height:170mm;box-shadow:none}}</style></head><body>${certificateHTML(true)}<script>window.onload=()=>window.print()<\/script></body></html>`);win.document.close()}
function login(name){studentName=name;localStorage.setItem('gis_lab_name',studentName);const idKey='gis_lab_student_id_'+studentName.toLowerCase();studentId=localStorage.getItem(idKey)||makeId();localStorage.setItem(idKey,studentId);progress=readProgress(studentId);showApp()}
function logout(){studentName='';localStorage.removeItem('gis_lab_name');document.getElementById('app-shell').classList.add('hidden');document.getElementById('login-screen').classList.remove('hidden');document.getElementById('student-name').value='';}
window.addEventListener('DOMContentLoaded',()=>{setSyncStatus('local','Saved on this device');document.getElementById('login-form').addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('student-name').value.trim().replace(/\s+/g,' ');if(!name)return;login(name)});document.getElementById('logout-button').onclick=logout;document.getElementById('leaderboard-shortcut').onclick=()=>goToModule(9);document.getElementById('menu-toggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');if(studentName){localStorage.setItem('gis_lab_student_id_'+studentName.toLowerCase(),studentId);showApp()}else document.getElementById('student-name').focus();document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();renderHome()})});
